case MSG_MAGIC_DRAIN:
{
    if (you.has_mutation(MUT_HP_CASTING))
        mpr("You feel momentarily drained.");
    else
        mprf(MSGCH_WARN, "You suddenly feel drained of magical energy!");
    break;
}

